sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var P = 'x_2056099_indust_0_';
    var passed = 0;
    var total = 0;
    total++;
    var grActive = new GlideRecord(P + 'mat_master');
    grActive.addActiveQuery();
    grActive.query();
    var activeCount = 0;
    while (grActive.next()) activeCount++;
    assertEqual({ name: 'Active products exist', shouldbe: true, value: activeCount > 0 });
    passed++;
    total++;
    var grProd = new GlideRecord(P + 'mat_master');
    grProd.addActiveQuery();
    grProd.setLimit(1);
    grProd.query();
    if (grProd.next()) {
        assertEqual({ name: 'Product name populated', shouldbe: true, value: (grProd.getValue('name') || '').length > 0 });
        assertEqual({ name: 'Unit price displayed', shouldbe: true, value: parseFloat(grProd.getValue('standard_cost')) > 0 });
        assertEqual({ name: 'UOM populated', shouldbe: true, value: (grProd.getValue('unit_of_measure') || '').length > 0 });
        passed++;
    }
    total++;
    var grDetail = new GlideRecord(P + 'mat_master');
    grDetail.addActiveQuery();
    grDetail.addNotNullQuery('name');
    grDetail.addNotNullQuery('standard_cost');
    grDetail.setLimit(1);
    grDetail.query();
    assertEqual({ name: 'Product with detail info exists', shouldbe: true, value: grDetail.next() });
    assertEqual({ name: 'Product can be opened by ID', shouldbe: true, value: (grDetail.getValue('material_product_id') || '').length > 0 });
    passed++;
    total++;
    var grAll = new GlideRecord(P + 'mat_master');
    grAll.query();
    var allCount = 0;
    while (grAll.next()) allCount++;
    assertEqual({ name: 'Active query filters correctly', shouldbe: true, value: activeCount <= allCount });
    passed++;
    stepResult.setOutputMessage('Catalog: ' + passed + '/' + total + ' passed. ' + activeCount + ' active products.');
    return true;
})(outputs, steps, params, stepResult, assertEqual);
